CREATE TABLE conversation_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, platform VARCHAR(16) NOT NULL, user_id VARCHAR(64) NOT NULL, chat_id VARCHAR(64) NOT NULL, interaction_id VARCHAR(36) NOT NULL, "role" VARCHAR(16) NOT NULL, content TEXT NOT NULL, tool_call_id VARCHAR(128) NULL, tool_name VARCHAR(128) NULL, tool_is_error BOOLEAN NULL, created_at TEXT NOT NULL);
CREATE INDEX conversation_messages_platform_user_id_chat_id ON conversation_messages (platform, user_id, chat_id);
CREATE TABLE conversations (platform VARCHAR(16) NOT NULL, user_id VARCHAR(64) NOT NULL, chat_id VARCHAR(64) NOT NULL, revision BIGINT DEFAULT 0 NOT NULL, summary TEXT NULL, summarized_through_message_id BIGINT DEFAULT 0 NOT NULL, CONSTRAINT pk_conversations PRIMARY KEY (platform, user_id, chat_id));
CREATE TABLE group_log (id INTEGER PRIMARY KEY AUTOINCREMENT, platform VARCHAR(16) NOT NULL, chat_id VARCHAR(64) NOT NULL, message_id VARCHAR(64) NULL, sender_id VARCHAR(64) NULL, sender_username VARCHAR(64) NULL, sender_name VARCHAR(200) NULL, kind VARCHAR(24) NOT NULL, text TEXT NULL, "descriptor" VARCHAR(200) NULL, forward_from VARCHAR(128) NULL, reply_to_message_id VARCHAR(64) NULL, sent_at TEXT NOT NULL);
CREATE INDEX group_log_platform_chat_id_sent_at ON group_log (platform, chat_id, sent_at);
CREATE UNIQUE INDEX group_log_platform_chat_id_message_id ON group_log (platform, chat_id, message_id);
CREATE TABLE group_log_digests (platform VARCHAR(16) NOT NULL, chat_id VARCHAR(64) NOT NULL, "day" VARCHAR(10) NOT NULL, content TEXT NOT NULL, CONSTRAINT pk_group_log_digests PRIMARY KEY (platform, chat_id, "day"));
CREATE TABLE chat_diary (platform VARCHAR(16) NOT NULL, chat_id VARCHAR(64) NOT NULL, "day" VARCHAR(10) NOT NULL, content TEXT NOT NULL, CONSTRAINT pk_chat_diary PRIMARY KEY (platform, chat_id, "day"));
CREATE TABLE scheduled_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, platform VARCHAR(16) NOT NULL, user_id VARCHAR(64) NOT NULL, chat_id VARCHAR(64) NOT NULL, title VARCHAR(200) NULL, prompt TEXT NOT NULL, recurrence VARCHAR(100) NOT NULL, timezone VARCHAR(64) NOT NULL, next_fire_at TEXT NOT NULL, paused BOOLEAN DEFAULT 0 NOT NULL, self_initiated BOOLEAN DEFAULT 0 NOT NULL, chat_is_private BOOLEAN DEFAULT 1 NOT NULL, "language" VARCHAR(16) NULL, creator_message_id VARCHAR(64) NULL, creator_thread_id VARCHAR(64) NULL, creator_username VARCHAR(64) NULL, creator_display_name VARCHAR(200) NULL);
CREATE INDEX scheduled_tasks_platform_user_id ON scheduled_tasks (platform, user_id);
CREATE INDEX scheduled_tasks_paused_next_fire_at ON scheduled_tasks (paused, next_fire_at);
CREATE TABLE memories (id INTEGER PRIMARY KEY AUTOINCREMENT, platform VARCHAR(16) NOT NULL, scope VARCHAR(16) NOT NULL, owner_id VARCHAR(64) NOT NULL, content TEXT NOT NULL);
CREATE INDEX memories_platform_scope_owner_id ON memories (platform, scope, owner_id);
CREATE TABLE telegram_stickers (id INTEGER PRIMARY KEY AUTOINCREMENT, file_unique_id VARCHAR(128) NOT NULL, file_id TEXT NOT NULL, set_name VARCHAR(64) NOT NULL, emoji VARCHAR(32) NULL, thumbnail_file_id TEXT NULL, description TEXT NULL, describe_attempts INT DEFAULT 0 NOT NULL, CONSTRAINT chk_telegram_stickers_signed_integer_describe_attempts CHECK (describe_attempts BETWEEN -2147483648 AND 2147483647));
CREATE UNIQUE INDEX telegram_stickers_file_unique_id ON telegram_stickers (file_unique_id);
CREATE INDEX telegram_stickers_set_name ON telegram_stickers (set_name);
CREATE TABLE telegram_sticker_sets ("name" VARCHAR(64) NOT NULL PRIMARY KEY, refreshed_at TEXT NOT NULL);
CREATE TABLE telegram_chat_sticker_sets (chat_id BIGINT NOT NULL, set_name VARCHAR(64) NOT NULL, seen_count INT DEFAULT 0 NOT NULL, last_seen_at TEXT NOT NULL, learned_at TEXT NULL, CONSTRAINT pk_telegram_chat_sticker_sets PRIMARY KEY (chat_id, set_name), CONSTRAINT chk_telegram_chat_sticker_sets_signed_integer_seen_count CHECK (seen_count BETWEEN -2147483648 AND 2147483647));
CREATE TABLE telegram_chat_stickers (chat_id BIGINT NOT NULL, file_unique_id VARCHAR(128) NOT NULL, seen_count INT DEFAULT 0 NOT NULL, last_seen_at TEXT NOT NULL, CONSTRAINT pk_telegram_chat_stickers PRIMARY KEY (chat_id, file_unique_id), CONSTRAINT chk_telegram_chat_stickers_signed_integer_seen_count CHECK (seen_count BETWEEN -2147483648 AND 2147483647));
CREATE INDEX telegram_chat_stickers_chat_id_last_seen_at ON telegram_chat_stickers (chat_id, last_seen_at);
CREATE TABLE telegram_pending_updates (update_id BIGINT NOT NULL PRIMARY KEY, payload TEXT NOT NULL, received_at TEXT NOT NULL);
CREATE INDEX telegram_pending_updates_received_at ON telegram_pending_updates (received_at);
CREATE TABLE telegram_polls (poll_id VARCHAR(64) NOT NULL PRIMARY KEY, chat_id BIGINT NOT NULL, "options" TEXT NOT NULL, correct_option_index INT NULL, created_at TEXT NOT NULL, CONSTRAINT chk_telegram_polls_signed_integer_correct_option_index CHECK (correct_option_index BETWEEN -2147483648 AND 2147483647));
CREATE INDEX telegram_polls_created_at ON telegram_polls (created_at);
